+      maxRequests: 100,
+      maxDocumentPages: 20,
+      timeoutMs: 120000,
+      concurrency: 3,
+    });
+    expect(collect.mock.calls[0]![1]).toEqual({
+      runId: context.runId,
+      signal: context.signal,
+      log: context.log,
+      progress: context.progress,
