+  ["technology", ["firecrawl", "openalex"]],
+  ["bmw_sales", ["firecrawl", "local_documents"]],
+  ["bmw_strategy", ["firecrawl", "local_documents"]],
+];
+function original(
+  provider: ResearchProviderId,
+  suffix: string,
+  overrides: Partial<CollectedItem> = {},
