+  for (const entry of items) {
+    ctx.signal.throwIfAborted();
+    const requirement = entry.layer === "requirements" ? entry.item as Requirement : undefined;
+    if (requirement?.priority) {
+      const branch = branchFor(requirement.priority, entry.id, ctx.log);
+      result.set(entry.id, branch);
+      ctx.log(`${entry.id}: existing priority ${requirement.priority} preserved (including any human override); routed to out-${branch}.`);
+    } else if (requirement?.score) {
+      const values = Object.fromEntries(ScoreFactor.options.map((factor) => [factor, requirement.score!.factors[factor].value])) as Record<ScoreFactor, number>;
+      const total = weightedTotal(values, scoring.weights);
+      const priority = priorityForScore(total, scoring.thresholds);
+      const branch = branchFor(priority, entry.id, ctx.log);
+      result.set(entry.id, branch);
+      ctx.log(`${entry.id}: reused existing factor values with current Settings weights/thresholds; total ${total}/100, priority ${priority}, out-${branch}. Stored score unchanged.`);
+      for (const factor of ScoreFactor.options) ctx.log(`${entry.id}: ${factor}=${values[factor]}/5, weight=${scoring.weights[factor]}; ${requirement.score.factors[factor].note}`);
