+    ctx.log(`Provisional scoring batch ${index + 1}/${groups.length}: ${batch.length} primary items.`);
+    const { object, model } = await generate(ctx, { system: SCORING_SYSTEM, prompt: JSON.stringify(payload(batch)), schema: Scores, tier: params.model });
