+]);
+const ANNOTATIONS = new Set(["type", "title", "description", "enum", "const", "default", "required"]);
+const LOCAL_CONSTRAINTS = new Set([
+  "minimum", "maximum", "exclusiveMinimum", "exclusiveMaximum", "multipleOf", "minLength", "maxLength",
+  "pattern", "maxItems", "uniqueItems", "minProperties", "maxProperties", "propertyNames",
+]);
